const circuit='https://el34world.com/charts/Schematics/files/fender/Fender_TWIN_REVERB_AB763.pdf';
const period='https://www.vintageguitarandbass.com/fender/catalogues/1968_33.php';
const specimen='https://retrofret.com/products/fender-twin-reverb-ac-568-wfactory-jbls-large-combo-tube-amplifier-1968-13479';
export const TWIN_FEATURES=[
 {id:'inputs',label:'Inputs',side:'front',offset:[0,-25],title:'Two ways into each channel.',body:'Each channel has two quarter-inch inputs. In the AB763 family, input 2 attenuates the signal compared with input 1 when used on its own. It can give a hot pickup more room before the first stage overloads.',attributes:[['Connections','Two Normal · two Vibrato'],['Input 1','Higher sensitivity'],['Input 2','About 6 dB lower · used alone']],listen:'Try the same guitar and control settings in inputs 1 and 2. Input 2 should sound quieter and may clean up an overloaded first stage. Adjusting the volume afterward changes how you hear the comparison.',together:'The Normal and Vibrato channels have separate volume and tone controls. The reverb and tremolo belong to the Vibrato channel in the AB763 circuit. These are different signal paths, not simply four equivalent sockets.',choice:'Offering a less-sensitive input plausibly accommodates stronger pickup signals without a separate pad switch. This is an engineering interpretation, not a documented Fender design statement.',extraTitle:'A switching-jack circuit',extra:'The approximately 6 dB comparison assumes one occupied input in a channel. Plugging into both changes the jack/resistor network. AB763 is the circuit-family reference; the selected silver-panel specimen is not authenticated as AB763.',sources:[[circuit,'Fender AB763 schematic · family reference']],detail:'Hotspot positions follow the shared panel study. Input impedances and switching behavior should be checked against the individual amp’s actual circuit.'},
 {id:'reverb',label:'Reverb',side:'front',offset:[-15,-48],title:'Space made by springs.',body:'The Reverb control blends a spring-generated echoing tail with the dry sound. At modest settings it adds depth; higher settings make the Twin’s ringing, splashy texture a much larger part of the note.',attributes:[['Effect','Physical spring reverb'],['Control','Amount of returned reverb'],['Circuit context','Tube drive and recovery · Vibrato channel']],listen:'Listen to what follows a short, muted note. The spring tail has its own texture; increasing Reverb adds more of that return rather than simply lengthening a digital decay setting.',together:'The clean output stage can keep the dry attack distinct while the spring return hangs behind it. Guitar output, channel settings, the tank and its condition all influence the resulting splash and noise.',choice:'Built-in reverb plausibly offered spacious sound without a separate effects unit. The circuit proves the implementation, not the designer’s complete motivation.',extraTitle:'A mechanical effect',extra:'The family circuit sends signal through a transformer and spring tank, then amplifies the return. The tank is not yet modeled here; the hotspot identifies the control, not a verified tank specification for this vintage specimen.',sources:[[circuit,'Fender AB763 schematic · reverb path']],detail:'No exact tank model or spring count is asserted for the selected 1968 reference.'},
 {id:'vibrato',label:'Vibrato / tremolo',side:'front',offset:[30,-12],title:'A pulse, rather than a pitch bend.',body:'Fender labels these controls “Vibrato,” but the effect in this Twin family is tremolo: rhythmic changes in level. Speed sets the pulse rate; Intensity sets how deep the volume movement becomes.',attributes:[['What changes','Amplitude · not deliberate pitch modulation'],['Speed','Rate of the pulse'],['Intensity','Depth of the pulse']],listen:'Hold a chord and hear the volume rise and fall. Compare a shallow shimmer with a deeper chop. Reverb adds a trailing space around that rhythm, making their interaction part of the Twin experience.',together:'The AB763 circuit uses an oscillator and optical element in the Vibrato channel. That implementation differs from Fender’s other tremolo designs; a shared panel label does not guarantee the same mechanism across amps.',choice:'Separate rate and depth controls plausibly let a player choose both the tempo and strength of the motion. That is an interpretation of the controls, not a recovered design brief.',extraTitle:'Name versus mechanism',extra:'This card uses “tremolo” for the amplitude effect while preserving the panel’s “Vibrato” wording. It is circuit-family context, not a claim that every early silver-panel circuit is identical.',sources:[[circuit,'Fender AB763 schematic · oscillator and optical element'],['https://www.fender.com/products/65-twin-reverb/','Fender modern reissue · terminology only']],detail:'The modern reissue is a secondary terminology reference, not proof of the selected vintage specimen’s circuit.'},
 {id:'grille-cloth',label:'Grille cloth',side:'front',cosmetic:true,title:'The silver-and-blue face.',body:'The silver/aqua woven grille is part of this early silver-panel look. It covers the speaker opening and gives the cabinet a recognizable texture without exposing the cones.',attributes:[['This study','Silver / aqua weave'],['Role','Speaker-front covering'],['Evidence','Period styling and dated specimen photographs']],listen:'Look for the cooler blue threads against the silver weave. Lighting and aging change how strongly those colors appear; this rendering is a material study, not a calibrated match.',together:'The cloth, aluminum edging and silver control panel work as one visual identity. Cloth can affect acoustic transmission, but we have no measurements establishing a tonal signature for this modeled weave.',choice:'Protection and a coherent updated appearance are plausible design considerations. We have not established why Fender chose this exact weave or color combination.',extraTitle:'Cloth is not circuit identification',extra:'A re-clothed vintage amp can look period-correct without retaining its factory fabric. Cosmetic features alone do not identify the chassis revision, speaker option or originality.',sources:[[period,'1968 Fender catalog · period appearance'],[specimen,'Dated 1968 Twin photographs']],detail:'Thread pitch, color, relief and mounted dimensions remain estimates. No unlicensed specimen photograph is embedded.'},
 {id:'drip-edge',label:'Drip edge',side:'front',cosmetic:true,title:'A frame for the early silver-panel look.',body:'The bright aluminum trim around the grille is commonly called “drip edge.” On this early silver-panel Twin, it gives the front opening a narrow reflective border distinct from the cloth and the control panel.',attributes:[['Feature','Aluminum grille surround'],['This reference','1968 early silver-panel appearance'],['Use it for','Cosmetic context · not circuit authentication']],listen:'Look at the thin highlight around the grille as you rotate the amp. That edge is a physical surround, rather than a stripe printed on the cloth.',together:'Together with the silver panel, blue lettering and silver/aqua cloth, the surround helps distinguish this appearance from the preceding black-panel design. It does not determine the amplifier’s tone.',choice:'A finished perimeter and an updated visual identity are plausible motivations. We have not found a primary design statement explaining this particular trim choice.',extraTitle:'A clue, not a serial number',extra:'Replacement trim, restored cloth and swapped chassis complicate dating. This feature supports an appearance comparison; use circuit drawings, component evidence and production records for stronger identification.',sources:[[period,'1968 Fender catalog · period appearance'],[specimen,'Dated 1968 Twin photographs']],detail:'Trim profile and dimensions are modeled estimates. The nickname does not establish a rain-management function.'}
];
